ROLE_LINE = {
    "scout": "the Scout of a small crew: the one who watches",
    "fixer": "the Fixer of a small crew: the one who turns people and makes the calls, unarmed and persuasive",
    "tech": "the Tech of a small crew: the one who quietly fixes and reroutes clockwork machines",
    "enforcer": "the Enforcer of a small crew: the big one who takes people and holds the line",
}

HEAD = ("Stylised character concept art for a video game, in the manner of a polished character design sheet: full body head to toe, one person, an expressive three-quarter pose "
        "with attitude that shows personality (never a stiff catalogue pose), a bold readable silhouette, plain warm light-grey studio backdrop with a soft ground shadow. ")
LINEAGE = ("Design lineage: a visitor from a nearby timeline, sharper and cleaner than any local; a memorable cut with a sculpted collar, asymmetric closures and layered panels; "
           "matte technical fabrics, clean seams, brushed chrome and matte metal hardware; no gold, no brass, no deco ornament, no period tailoring, no workwear uniform look, not cyberpunk, no neon, no glowing parts. "
           "Bare open face, no mask, no sunglasses, no helmet. ")
FIN = ("Finish: polished matte painted digital character concept art, crisp clean edges, slightly stylised proportions, soft even studio light, an expressive believable face. "
       "No text, no logos, no watermark.")


def prompt(role, p):
    return (HEAD + f"{p['who']}, {ROLE_LINE[role]}. Personality: {p['hook'].replace('[blend] ', '')} Face: {p['face']}. "
            f"Clothes: {p['outfit']}, built from sharp colour blocks: charcoal and ink-black base, one cool off-white panel, and {p['accent']} as the single accent. "
            f"Telling detail: {p['detail']}. " + LINEAGE + FIN)
